describe('handle', () => {
  it('creates a Zendesk ticket with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST');
      expect(req.url).toBe('https://mysub.zendesk.com/api/v2/tickets.json');
      expect(req.headers.get('authorization')).toBe('Bearer secret-token');
      expect(req.json).toEqual({
        ticket: {
          subject: 'https://app.intercom.com/a/apps/123/inbox/conversations/456',
          comment: { body: 'Intercom conversation ID: 456' },
        },
      });
      return jsonResponse({
        ticket: { id: 789, url: 'https://mysub.zendesk.com/api/v2/tickets/789.json' },
      }, 201);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '456',
          url: 'https://app.intercom.com/a/apps/123/inbox/conversations/456',
        },
        tag: { name: 'refund' },
      },
    };

    const config: ConnectorConfig = {
      zendeskSubdomain: 'mysub',
      zendeskAccessToken: 'secret-token',
      fetch,
    };

    const result = await handle(payload, config);
    expect(result.ticketId).toBe(789);
    expect(result.ticketUrl).toBe('https://mysub.zendesk.com/api/v2/tickets/789.json');
    expect(calls.length).toBe(1);
  });

  it('uses Bearer token authentication', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.headers.get('authorization')).toBe('Bearer my-access-token');
      return jsonResponse({ ticket: { id: 1, url: 'https://sub.zendesk.com/api/v2/tickets/1.json' } }, 201);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: { type: 'conversation', id: '1', url: 'https://intercom.com/conversations/1' },
        tag: { name: 'refund' },
      },
    };

    await handle(payload, {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'my-access-token',
      fetch,
    });

    expect(calls[0].headers.get('authorization')).toBe('Bearer my-access-token');
  });

  it('maps conversation.url to subject and conversation.id to comment.body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as { ticket: { subject: string; comment: { body: string } } };
      expect(body.ticket.subject).toBe('https://intercom.com/conv/999');
      expect(body.ticket.comment.body).toBe('Intercom conversation ID: 999');
      return jsonResponse({ ticket: { id: 2, url: 'https://sub.zendesk.com/api/v2/tickets/2.json' } }, 201);
    });

    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: { type: 'conversation', id: '999', url: 'https://intercom.com/conv/999' },
        tag: { name: 'refund' },
      },
    };

    await handle(payload, {
      zendeskSubdomain: 'sub',
      zendeskAccessToken: 'token',
      fetch,
    });

    expect(calls.length).toBe(1);
  });

  it('throws when data.item is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { type: 'notification_event', topic: 'conversation_part.tag.created', data: {} } as unknown as IntercomWebhookPayload;

    await expect(handle(payload, { zendeskSubdomain: 'sub', zendeskAccessToken: 'token', fetch }))
      .rejects.toThrow('Missing required field: data.item');
  });

  it('throws when data.item.type is not conversation', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'user', id: '1', url: 'https://intercom.com/users/1' } },
    };

    await expect(handle(payload, { zendeskSubdomain: 'sub', zendeskAccessToken: 'token', fetch }))
      .rejects.toThrow("Expected data.item.type === 'conversation', got 'user'");
  });

  it('throws when data.item.id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '', url: 'https://intercom.com/conv/1' } },
    };

    await expect(handle(payload, { zendeskSubdomain: 'sub', zendeskAccessToken: 'token', fetch }))
      .rejects.toThrow('Missing required field: data.item.id');
  });

  it('throws when data.item.url is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '1', url: '' } },
    };

    await expect(handle(payload, { zendeskSubdomain: 'sub', zendeskAccessToken: 'token', fetch }))
      .rejects.toThrow('Missing required field: data.item.url');
  });

