    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: {
        item: { type: 'conversation', id: '1', url: 'https://intercom.com/conv/1' },
        tag: { name: 'spam' },
