  });

  it('throws on 500 response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Internal Server Error' }, 500));
    const payload: IntercomWebhookPayload = {
      type: 'notification_event',
      topic: 'conversation_part.tag.created',
      data: { item: { type: 'conversation', id: '1', url: 'https://intercom.com/conv/1' }, tag: { name: 'refund' } },
