  if (!payload.data.item.url) {
    throw new Error('Missing required field: data.item.url');
  }

  const tagName = payload.data.tag?.name;
  if (tagName && tagName !== 'refund') {
    return {
      ticketId: 0,
      ticketUrl: '',
      skipped: true,
      reason: `Tag '${tagName}' is not 'refund'`,
    };
  }

  const conversationId = payload.data.item.id;
  const conversationUrl = payload.data.item.url;

  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets.json`;
  const requestBody = {
    ticket: {
      subject: conversationUrl,
      comment: {
        body: `Intercom conversation ID: ${conversationId}`,
      },
